        }
        // Try a second call immediately after to emulate reentrant attempt (though not true reentrancy)
        try c.initialize(_baseToken, _nft, _virtualBaseTokenReserves, _virtualNftReserves, _changeFee, _feeRate, _merkleRoot, _useStolenNftOracle, _payRoyalties) returns (bool) {
